import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> tags in html.

    Tag matching is case-insensitive. Returns "" when there is no
    title element or its closing tag is missing. Performs no I/O:
    html is already fetched, and this function must not use the network.
    """
    match = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_simple_title() -> None:
    assert title_of("<html><head><title>Hi</title></head></html>") == "Hi"


def test_missing_title() -> None:
    assert title_of("<html><body>no head</body></html>") == ""


def test_uppercase_tags() -> None:
    assert title_of("<TITLE>Caps</TITLE>") == "Caps"


def test_first_title_wins() -> None:
    assert title_of("<title>a</title><title>b</title>") == "a"


def test_unclosed_title() -> None:
    assert title_of("<title>oops") == ""
